import * as THREE from 'three/webgpu';
import { texture, uv, vec2, vec4, mix, float, uniform } from 'three/tsl';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.name = 'journal-card-1';

  const width = 1.6;
  const height = 1.0;
  const geometry = new THREE.PlaneGeometry(width, height);

  const map = ctx.textureLoader.load('/prism-mock/home/nodes/orb-decor.png');
  map.colorSpace = THREE.SRGBColorSpace;

  const material = new THREE.MeshBasicNodeMaterial();

  const texNode = texture(map, uv());

  const inkColor = vec4(0x16 / 255, 0x16 / 255, 0x1d / 255, 1.0);
  const surfaceColor = vec4(0x0b / 255, 0x0b / 255, 0x10 / 255, 1.0);
  const gradientMix = uniform(0.35);

  const vUv = uv();
  const gradient = mix(surfaceColor, inkColor, vUv.y);

  const grainSeed = vUv.x.mul(1024.0).add(vUv.y.mul(768.0));
  const grain = grainSeed.sin().mul(43758.5453).fract().sub(0.5).mul(0.035);

  const engineeredBg = vec4(
    gradient.r.add(grain),
    gradient.g.add(grain),
    gradient.b.add(grain),
    1.0
  );

  const finalColor = mix(engineeredBg, texNode, texNode.a);

  material.colorNode = finalColor;
  material.transparent = false;

  const mesh = new THREE.Mesh(geometry, material);
  mesh.position.set(-3.2, -0.3, 0);
  mesh.rotation.set(0, 0, 0);
  mesh.scale.set(1, 1, 1);

  group.add(mesh);

  group.userData.handlers = {};

  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (map) map.dispose();
  };

  return group;
}
